-- 41_estimates_tracker.sql -- full file; if the editor truncates, run 41_part1.sql then 41_part2.sql

alter table estimates add column if not exists stage           text;
alter table estimates add column if not exists pipeline_status text;
alter table estimates add column if not exists requested_date  date;
alter table estimates add column if not exists monday_id       text;
drop index if exists estimates_monday_id_key;
create unique index estimates_monday_id_key on estimates (monday_id);


update estimates e set lead_id = l.lead_id from leads l where e.lead_id is null and lower(trim(e.client_name)) = lower(trim(l.name));
update estimates e set job_id  = j.job_id  from jobs  j where e.job_id  is null and lower(trim(e.client_name)) = lower(trim(j.client_name));

select
  (select count(*) from estimates where monday_id is not null) as imported,
  (select count(distinct stage) from estimates) as stages,
  (select count(*) from estimates where status = 'Accepted') as accepted,
  (select count(*) from estimates where lead_id is not null) as linked_to_lead;
